-- WARREGIONS(AU)[32+64]-V16.01
-- Do not edit this file. Any change breaks the decoder.
local _kskxoj = 250
local _tpzveq = 229
local _jnzdlt = 250
local _gxluuy = ""

local _eqnhjn = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _qfwijr(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _vdjflz(d)
	d = d:gsub("[^" .. _eqnhjn .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_eqnhjn:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _plpnmf = _vdjflz(_gxluuy)
local _xrpery = { _kskxoj, _tpzveq, _jnzdlt }
local _xbkrsy = {}
for i = 1, #_plpnmf do
	_xbkrsy[i] = string.char(_qfwijr(_plpnmf:byte(i), _xrpery[(i - 1) % 3 + 1]))
end

local _rciusz = load or loadstring
local _ukprop, _jduqop = _rciusz(table.concat(_xbkrsy), "=w")
if not _ukprop then
	gg.alert("Corrupted file: " .. tostring(_jduqop))
	os.exit()
end
_ukprop()
